### 서버사이드에서 쿠키 값을 불러오기 위한 훅을 추가했습니다.
```typescript
// @/hooks/useServerCookie.ts
import { cookies } from 'next/headers'

export function useServerCookie() {
  if (typeof window !== 'undefined') {
    throw new Error('This hook should be used in server-side only')
  }

  const cookieStore = cookies()
  const token = cookieStore.get('Auth-token')?.value!

  return { token }
}

```

### 로그인한 유저의 정보를 가져오는 API를 추가하였습니다.
```typescript
import { useServerCookie } from '@/hooks/useServerCookie'
import { apiServer } from '@/services/apiServices'
import { NextResponse } from 'next/server'

export async function GET(_request: Request) {
  const { token } = useServerCookie()
  try {
    const response = await apiServer.get(`/members/profile`, {
      headers: {
        Authorization: 'Bearer ' + token,
      },
    })

    return NextResponse.json(response)
  } catch (error: any) {
    return NextResponse.json(
      { error: error.response.data.message },
      { status: error.response.status },
    )
  }
}
```

### 현재 로그인한 유저의 정보와 로그인 여부를 반환하는 훅을 추가하였습니다.
```typescript
import { useEffect, useState } from 'react'
import { validateToken } from '@/services/auth'
import { UserProfileResBody } from '@/types'
import { useQuery } from '@tanstack/react-query'
import Cookies from 'js-cookie'
import { usePathname } from 'next/navigation'

export const useValidate = () => {
  const token = Cookies.get('Auth-token')
  return useQuery({
    queryKey: ['validateToken', token],
    queryFn: async () => {
      const res = await validateToken()
      if (!res) {
        Cookies.remove('Auth-token')
        alert('올바르지 않은 토큰입니다. 다시 로그인해주세요.')
      }

      return res
    },
    enabled: !!token,
  })
}

export const useCurrentUser = () => {
  const pathname = usePathname()
  const validateQuery = useValidate()

  const [isLoggedIn, setIsLoggedIn] = useState<boolean>(
    () => !!Cookies.get('Auth-token'),
  )
  const [currentUser, setCurrentUser] = useState<
    UserProfileResBody | undefined
  >(undefined)

  useEffect(() => {
    if (validateQuery.isError) {
      setIsLoggedIn(false)
      setCurrentUser(undefined)
    } else if (validateQuery.data) {
      setIsLoggedIn(true)
      setCurrentUser(validateQuery.data)
    }
  }, [validateQuery, pathname])

  return { currentUser, isLoggedIn }
}

```

### Context API를 사용해 로그인 여부 확인을 할 수 있는 AuthProvider를 추가했습니다.
```typescript
'use client'

import React, { createContext, useContext, useEffect, useMemo } from 'react'
import { useCurrentUser } from '@/hooks/useCurrentUser'
import { UserProfileResBody } from '@/types'
import { usePathname, useRouter } from 'next/navigation'

interface AuthProviderProps {
  children: React.ReactNode
}

const AuthContext = createContext<{
  currentUser: UserProfileResBody | undefined
  isLoggedIn: boolean
}>({
  currentUser: undefined,
  isLoggedIn: false,
})

//  로그인이 필요한 url
const authNeededPages = [
  '/space/create',
  '/space/:spaceId/setting',
  '/user/setting',
]

//  로그인이 된 후에 접근할 수 없는 url
const authProhibitedPages = ['/login', '/register']

export function AuthProvider({ children }: AuthProviderProps) {
  const pathname = usePathname()
  const router = useRouter()
  const { currentUser, isLoggedIn } = useCurrentUser()

  const contextValue = useMemo(
    () => ({ currentUser, isLoggedIn }),
    [currentUser, isLoggedIn],
  )

  useEffect(() => {
    //  로그인이 되어있으면 로그인, 회원가입 페이지 접근 불가
    if (isLoggedIn && authProhibitedPages.includes(pathname)) {
      router.push('/')
    }
    if (!isLoggedIn && authNeededPages.includes(pathname)) {
      alert('로그인이 필요합니다.')
      router.push('/login')
    }
  }, [isLoggedIn, pathname, router])

  return (
    <AuthContext.Provider value={contextValue}>{children}</AuthContext.Provider>
  )
}

export function useAuth() {
  const context = useContext(AuthContext)
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider')
  }
  return context
}
```

This has been one of the most weird functions I ever decompiled. I will share a few tricks I learnt. In short, I tried inlining as much as possible by removing all the temps.

---

```c
switch (self->step) {
...
case 2:
        isEntityAlive = 0;
        if (self->step != 2) {
            return;
        }
```
This was the output from M2C. As there is no way that `self->step` is different than `2`, deleting had no effect on the matching.

---

```c
var_v0 = self->step;
switch (var_v0) {
    case 1:
        ...
        if (statement) {
            self->step++;
        }
        ...
        D_SOME_VARIABLE = var_v0;
}
```

This was another very weird one. I couldn't understand why `D_SOME_VARIABLE` was assigned that way much further down the `case 1`. The way I fixed it is that `var_v0` was always `1` due to `case 1:`. By doing `D_SOME_VARIABLE = 1` I got a match.

---

```c
temp_a0_2 = D_80174C2C + 1;
...
D_80174C2C = temp_a0_2 & -(temp_a0_2 < 0x10);
```

To understand this madness I used a random C compiler I found online and tested in a `for` loop what's the output for all the given `temp_a0_2`. It seemed the value never changed but over `16` the value was always 0. I logically re-written that statement into something that made logically more sense for me and it matched, even if it looks very different from the original:

```c
D_80174C2C++;
D_80174C2C = D_80174C2C >= 16 ? 0 : D_80174C2C;
```
